begin isolation level serializable;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
set local role authenticated;
select throws_ok($$select public.board_ui_list('board-test')$$,'25001','BOARD_ISOLATION_UNSUPPORTED','board reads reject stale serializable snapshots');
select throws_ok($$select public.board_ui_detail('board-test',gen_random_uuid())$$,'25001','BOARD_ISOLATION_UNSUPPORTED','detail rejects stale authority');
select throws_ok($$select public.board_ui_create('board-test',gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'Title','Body','{}',false,false)$$,'25001','BOARD_ISOLATION_UNSUPPORTED','create rejects stale authority');
select throws_ok($$select public.board_ui_delete('board-test',gen_random_uuid(),gen_random_uuid(),1,true)$$,'25001','BOARD_ISOLATION_UNSUPPORTED','delete rejects stale authority');
select throws_ok($$select public.board_ui_notice('board-test',gen_random_uuid(),gen_random_uuid(),1,true,true)$$,'25001','BOARD_ISOLATION_UNSUPPORTED','notice rejects stale authority');
reset role;
set local role service_role;
select throws_ok($$select public.board_media_begin_upload(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'image/png',100,gen_random_uuid())$$,'25001','BOARD_ISOLATION_UNSUPPORTED','upload rejects stale authority');
select throws_ok($$select public.board_media_resolve_upload(gen_random_uuid(),gen_random_uuid())$$,'25001','BOARD_ISOLATION_UNSUPPORTED','resolve rejects stale authority');
select throws_ok($$select public.board_media_finalize_upload(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),100,100)$$,'25001','BOARD_ISOLATION_UNSUPPORTED','finalize rejects stale authority');
select throws_ok($$select public.board_media_revoke_upload(gen_random_uuid(),gen_random_uuid())$$,'25001','BOARD_ISOLATION_UNSUPPORTED','revoke rejects stale authority');
select throws_ok($$select public.board_media_resolve_read(gen_random_uuid(),gen_random_uuid())$$,'25001','BOARD_ISOLATION_UNSUPPORTED','image read rejects stale authority');
reset role;
select * from finish();
rollback;
